            Session.CampaignMission = world;
            return OrbitLayout.Build(Db, station);
        }

        static void Near(Vector3 expected, Vector3 actual, float tol, string what)
        {
            Assert.That(Vector3.Distance(expected, actual), Is.LessThanOrEqualTo(tol), $"{what}: expected {expected:F5}, got {actual:F5}");
        }

        [TestCaseSource(nameof(Cases))]
        public void Jumpgates(E e)
        {
            var o = Build(e.station);
            Assert.AreEqual(e.hasGate, o.hasJumpgate, "visible gate only in the system's jumpgateStation orbit");
            if (e.hasGate) Near(e.gate, o.jumpgate, PosTol, "landmark 1");
            Near(e.hidden, o.hiddenJumpgate, PosTol, "landmark 2");
            Assert.AreEqual(e.hiddenAngle, o.hiddenGateAngle, "A2");
            Assert.AreEqual(0f, o.hiddenJumpgate.y, "gates lie in y = 0");
        }

        [TestCaseSource(nameof(Cases))]
        public void SkyRotation(E e)
        {
            var o = Build(e.station);
            Near(e.sky, o.skyEuler, AngleTol, "R_sky euler");
        }

        [TestCaseSource(nameof(Cases))]
        public void SunPlacement(E e)
        {
            var o = Build(e.station);
            Assert.AreEqual(e.sunSlot, o.sunSlot, "sun slot");
            Assert.AreEqual(e.sunPitch, o.sunPitch, AngleTol, "sun pitch");
            Near(e.light, o.lightDirection, DirTol, "light direction (toward the sun)");
            Assert.AreEqual(1f, o.lightDirection.magnitude, 1e-4f, "unit light direction");
            Assert.AreEqual(e.sunTexture, o.sunTexture);
        }

        [TestCaseSource(nameof(Cases))]
        public void Planets(E e)
        {
            var o = Build(e.station);
            Assert.AreEqual(e.planets.Length, o.planets.Count, "one planet per station of the system, in its list order");
            for (int i = 0; i < e.planets.Length; i++)
            {
                var x = e.planets[i]; var p = o.planets[i];
                string at = $"planet {i} (station {x.station})";
                Assert.AreEqual(x.station, p.station, at);
                Assert.AreEqual(x.orbit, p.isOrbitPlanet, at + " orbit planet");
                Assert.AreEqual(x.scale, p.scale, ScaleTol, at + " scale");
                Assert.AreEqual(x.flip, p.flip, at + " flip");
                Assert.AreEqual(x.texture, p.texture, at + " texture");
                Assert.AreEqual(x.ring, p.ring, at + " ring");
                if (!x.orbit)
                {
                    Assert.AreEqual(x.slot, p.slot, at + " slot");
                    Assert.AreEqual(x.pitch, p.pitch, AngleTol, at + " pitch");
                    Assert.AreEqual(x.yaw, p.yaw, AngleTol, at + " yaw");
                }
                else
                {
                    Assert.AreEqual(0f, p.pitch, at + " orbit planet pitch");
                    Assert.AreEqual(0f, p.yaw, at + " orbit planet yaw");
                }
            }
        }

