            Assert.AreEqual(e.asteroids, o.asteroidCount, "count = nextInt(40) + 40");
            Assert.AreEqual(e.centre, o.asteroidCentre, "field centre");
        }

        [TestCaseSource(nameof(Cases))]
        public void SameLayoutOnEveryVisit(E e)
        {
            var a = Build(e.station);
            var b = Build(e.station);
            Assert.AreEqual(a.jumpgate, b.jumpgate);
            Assert.AreEqual(a.hiddenJumpgate, b.hiddenJumpgate);
            Assert.AreEqual(a.skyEuler, b.skyEuler);
            Assert.AreEqual(a.lightDirection, b.lightDirection);
            Assert.AreEqual(a.asteroidCentre, b.asteroidCentre);
            Assert.AreEqual(a.planets.Select(p => p.scale).ToArray(), b.planets.Select(p => p.scale).ToArray());
        }

        [Test]
        public void MissionZeroHalvesTheOrbitPlanet()
        {
            // StarSystem::StarSystem 0x15c89a: campaign mission 0 (the prologue, the menu backdrop): s = int(s * 0.5).
            var e = MissionZero;
            var o = Build(78, 0);
            var orbit = o.planets.Single(p => p.isOrbitPlanet);
            Assert.AreEqual(e.planets.Single(p => p.orbit).scale, orbit.scale, ScaleTol);
            var normal = Build(78, 20).planets.Single(p => p.isOrbitPlanet);
            Assert.AreEqual(normal.scale / 2f, orbit.scale, 1f / 65536f, "half of the free-play size (integer-truncated)");
            for (int i = 0; i < e.planets.Length; i++)
                if (!e.planets[i].orbit) Assert.AreEqual(e.planets[i].scale, o.planets[i].scale, ScaleTol, "the other draws are unchanged");
        }

        static readonly E MissionZero = new E { station = 78, hasGate = false, gate = V(0.0f, 0.0f), hidden = V(73037.422238f, 116521.608952f), hiddenAngle = 5840,
                    sky = new Vector3(4.667041f, 2.005488f, 5.407762f), sunSlot = 8, sunPitch = 0.02857f, light = new Vector3(-0.866281f, -0.014271f, 0.499353f),
                    asteroids = 50, centre = new Vector3(12298, 36830, 77237), sunTexture = "sun_009",
                    planets = new[] { new P(75, 11, 0.113898f, 2.87909f, 0.036148f, true, "planet_004_small", false, false),
                                      new P(76, 14, 0.13336f, 3.664297f, 0.03299f, true, "planet_010_small", false, false),
                                      new P(77, 15, -0.172669f, 3.926032f, 0.02948f, true, "planet_018_small", false, false),
                                      new P(78, 0, 0.0f, 0.0f, 0.278427f, false, "planet_000_big", true, false),
                                      new P(79, 16, -0.093285f, 4.187768f, 0.028778f, true, "planet_011_small", false, false) } };

        [Test]
        public void EveryPlanetSlotIsFreeAndClearOfTheSun()
        {
            // StarSystem::StarSystem: the other planets take slot nextInt(11) + 7 (7..17), never within 2 of the sun's,
            // never one taken; scale (nextInt(40) * 0.01 + 0.8) * 0.0351; pitch within +-2048 / 65536 of a turn; flipped
            // when their slot is past the sun's. Every original station.
            foreach (var sys in Db.Systems.Where(s => s.index < 34))
                foreach (int st in sys.stations)
                {
                    var o = Build(st);
                    var slots = new HashSet<int>();
                    foreach (var p in o.planets.Where(p => !p.isOrbitPlanet))
                    {
                        Assert.That(p.slot, Is.InRange(7, 17), $"station {st}");
                        Assert.That(Mathf.Abs(p.slot - o.sunSlot), Is.GreaterThanOrEqualTo(3), $"station {st}");
                        Assert.IsTrue(slots.Add(p.slot), $"station {st}: slot {p.slot} twice");
                        Assert.That(p.scale, Is.InRange(0.028076f, 0.041815f), $"station {st}");
                        Assert.That(Mathf.Abs(p.pitch), Is.LessThanOrEqualTo(2048f / 65536f * 2f * Mathf.PI + 1e-5f), $"station {st}");
                        Assert.AreEqual(p.slot > o.sunSlot, p.flip, $"station {st}: flip toward the sun");
                    }
                    Assert.AreEqual(1, o.planets.Count(p => p.isOrbitPlanet), $"station {st}: exactly one orbit planet");
                    Assert.That(o.asteroidCount, Is.InRange(40, 79), $"station {st}");
                    Assert.That(o.asteroidCentre.z, Is.InRange(20000f, 119999f), $"station {st}");
                    Assert.That(o.sunSlot, Is.InRange(4, 18), $"station {st}");
                }
        }
    }
